class BytesIOCopy(io.RawIOBase):
    """A binary stream backed by a real (temporary) file whose writes are
    also copied to another buffer.

    Being backed by an actual OS-level file (rather than an in-memory
    :class:`io.BytesIO`) means it has a real ``fileno()``, so it can be
    used with APIs that require a file descriptor, such as
    ``subprocess.run(..., stdout=sys.stdout)``.

    .. versionadded:: 8.2
    """

    def __init__(self, copy_to: io.BytesIO) -> None:
        super().__init__()
        self.copy_to = copy_to
        self._file = tempfile.TemporaryFile()

    def readable(self) -> bool:
        return True

    def writable(self) -> bool:
        return True

    def write(self, b: ReadableBuffer) -> int:
        self.copy_to.write(b)
        return self._file.write(b)

    def read(self, size: int = -1) -> bytes:
        return self._file.read(size)

    def getvalue(self) -> bytes:
        pos = self._file.tell()
        self._file.seek(0)
        data = self._file.read()
        self._file.seek(pos)
        return data

    def flush(self) -> None:
        self._file.flush()
        self.copy_to.flush()

    def fileno(self) -> int:
        return self._file.fileno()

    def close(self) -> None:
        self._file.close()
        super().close()

